:root {
  --bg: #faf8f5;
  --surface: #ffffff;
  --surface-2: #f3efe9;
  --ink: #1a1a1a;
  --ink-2: #2c2c2c;
  --muted: #595959;       /* 7.0:1 on --bg */
  --line: #d8d2c7;
  --line-strong: #8a8276; /* 3.4:1 on --bg, for borders */
  --accent: #8b3a1f;      /* terracotta, 6.7:1 on --bg */
  --accent-ink: #ffffff;
  --sale: #8a2d1a;        /* deep red for sale text on bg */
  --focus: #1a4fb8;       /* accessible focus blue */
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-sm: 0 1px 2px rgba(20,16,10,.06), 0 2px 8px rgba(20,16,10,.04);
  --shadow-md: 0 4px 14px rgba(20,16,10,.08), 0 12px 32px rgba(20,16,10,.06);
  --maxw: 1200px;
  --gap: clamp(16px, 2.4vw, 28px);
  --font-sans: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-serif: "Fraunces", "Cormorant Garamond", "Source Serif Pro", Georgia, "Times New Roman", serif;
}

/* ============ Reset / base ============ */
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
img, svg { display: block; max-width: 100%; }
button { font: inherit; color: inherit; cursor: pointer; }
a { color: var(--ink); text-decoration: none; }
a:hover { text-decoration: underline; text-underline-offset: 3px; }
ul { list-style: none; padding: 0; margin: 0; }
h1, h2, h3 { font-family: var(--font-serif); font-weight: 600; letter-spacing: -0.01em; line-height: 1.15; margin: 0; }
p { margin: 0; }

/* ============ Utilities ============ */
.container { max-width: var(--maxw); margin: 0 auto; padding: 0 clamp(16px, 4vw, 32px); }
.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}
.skip-link {
  position: absolute; left: 8px; top: -40px;
  background: var(--ink); color: #fff; padding: 10px 14px;
  border-radius: 8px; z-index: 1000; font-weight: 600;
}
.skip-link:focus { top: 8px; outline: 3px solid var(--focus); outline-offset: 2px; }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  margin-bottom: 8px;
}

/* ============ Buttons ============ */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px;
  padding: 12px 20px;
  border-radius: 999px;
  border: 1.5px solid transparent;
  font-weight: 600;
  font-size: 15px;
  line-height: 1;
  transition: transform .12s ease, background .15s ease, color .15s ease, border-color .15s ease;
  text-decoration: none;
  min-height: 44px;
}
.btn:hover { text-decoration: none; }
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--ink); color: #fff; border-color: var(--ink); }
.btn-primary:hover { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.btn-ghost { background: transparent; color: var(--ink); border-color: var(--line-strong); }
.btn-ghost:hover { background: var(--ink); color: #fff; border-color: var(--ink); }

.link-arrow {
  display: inline-flex; align-items: center; gap: 6px;
  font-weight: 600; color: var(--ink);
  border-bottom: 1.5px solid var(--line-strong);
  padding-bottom: 2px;
}
.link-arrow:hover { color: var(--accent); border-color: var(--accent); text-decoration: none; }

/* ============ Header ============ */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(250, 248, 245, 0.92);
  backdrop-filter: saturate(140%) blur(8px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding-top: 14px; padding-bottom: 14px;
}
.brand { display: inline-flex; align-items: center; gap: 10px; color: var(--ink); }
.brand:hover { text-decoration: none; }
.brand-name {
  font-family: var(--font-serif);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.primary-nav ul { display: flex; gap: 28px; justify-content: center; }
.primary-nav a {
  font-weight: 500; font-size: 15px;
  padding: 8px 4px;
  border-bottom: 2px solid transparent;
}
.primary-nav a:hover { text-decoration: none; border-bottom-color: var(--accent); color: var(--accent); }

.header-actions { display: flex; align-items: center; gap: 10px; }
.search {
  display: flex; align-items: center;
  background: var(--surface);
  border: 1.5px solid var(--line);
  border-radius: 999px;
  padding: 4px 6px 4px 14px;
  min-width: 220px;
}
.search:focus-within { border-color: var(--ink); outline: 2px solid var(--focus); outline-offset: 1px; }
.search input {
  flex: 1; min-width: 0;
  border: 0; outline: 0; background: transparent;
  padding: 8px 0;
  font-size: 14px;
  color: var(--ink);
}
.search input::placeholder { color: var(--muted); }
.search button {
  background: var(--ink); color: #fff;
  border: 0; border-radius: 999px;
  width: 34px; height: 34px;
  display: inline-flex; align-items: center; justify-content: center;
}
.search button:hover { background: var(--accent); }

.icon-btn {
  position: relative;
  background: transparent; border: 1.5px solid transparent;
  border-radius: 999px;
  width: 42px; height: 42px;
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--ink);
}
.icon-btn:hover { background: var(--surface); border-color: var(--line); }
.cart-count {
  position: absolute; top: -2px; right: -2px;
  background: var(--accent); color: var(--accent-ink);
  font-size: 11px; font-weight: 700;
  min-width: 18px; height: 18px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  padding: 0 5px;
  border: 2px solid var(--bg);
}

/* ============ Hero ============ */
.hero { padding: clamp(40px, 6vw, 80px) 0 clamp(40px, 5vw, 64px); }
.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(24px, 5vw, 64px);
  align-items: center;
}
.hero-copy h1 {
  font-size: clamp(36px, 5.6vw, 64px);
  margin: 6px 0 18px;
}
.lede { font-size: clamp(16px, 1.6vw, 19px); color: var(--ink-2); max-width: 52ch; }
.hero-cta { display: flex; flex-wrap: wrap; gap: 12px; margin: 28px 0 24px; }
.hero-meta {
  display: flex; flex-wrap: wrap; gap: 18px 28px;
  color: var(--muted); font-size: 14px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
}
.hero-meta li { position: relative; padding-left: 22px; }
.hero-meta li::before {
  content: ""; position: absolute; left: 0; top: 6px;
  width: 14px; height: 8px;
  border-left: 2px solid var(--accent);
  border-bottom: 2px solid var(--accent);
  transform: rotate(-45deg);
}

.hero-visual {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 14px;
  aspect-ratio: 5 / 4.4;
  min-height: 360px;
}
.hero-tile {
  border-radius: var(--radius);
  background: var(--surface-2);
  box-shadow: var(--shadow-sm);
  position: relative;
  overflow: hidden;
}
.hero-tile::after {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(120% 80% at 30% 20%, rgba(255,255,255,.6), transparent 60%);
}
.tile-a {
  grid-row: 1 / span 2;
  background:
    linear-gradient(160deg, #d8c3a5 0%, #b89272 60%, #8c6a4a 100%);
}
.tile-b { background: linear-gradient(150deg, #e8dccd 0%, #c8b89a 100%); }
.tile-c { background: linear-gradient(150deg, #2d3a36 0%, #485f57 100%); }

/* ============ Section heads ============ */
.section-head {
  display: flex; align-items: end; justify-content: space-between;
  gap: 16px; flex-wrap: wrap;
  margin-bottom: clamp(20px, 2.4vw, 32px);
}
.section-head h2 { font-size: clamp(26px, 3.2vw, 38px); }
.section-link {
  font-weight: 600; color: var(--ink);
  border-bottom: 1.5px solid var(--ink);
  padding-bottom: 2px;
}
.section-link:hover { color: var(--accent); border-color: var(--accent); text-decoration: none; }

/* ============ Categories ============ */
.categories { padding: clamp(32px, 4vw, 56px) 0; }
.cat-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: var(--gap);
}
.cat-card {
  display: flex; flex-direction: column; justify-content: flex-end;
  aspect-ratio: 3 / 4;
  padding: 16px;
  border-radius: var(--radius);
  background: var(--surface-2);
  border: 1px solid transparent;
  color: var(--ink);
  position: relative;
  overflow: hidden;
  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
}
.cat-card::before {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,.15) 100%);
  pointer-events: none;
}
.cat-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); border-color: var(--line); text-decoration: none; }
.cat-card[data-cat="home"]    { background: linear-gradient(160deg, #e8dccd, #c9b89a); }
.cat-card[data-cat="apparel"] { background: linear-gradient(160deg, #cfd8d3, #98aaa2); }
.cat-card[data-cat="kitchen"] { background: linear-gradient(160deg, #efe1d1, #c9a986); }
.cat-card[data-cat="paper"]   { background: linear-gradient(160deg, #efe9df, #cdc2b0); }
.cat-card[data-cat="bath"]    { background: linear-gradient(160deg, #d9dfe5, #aab4be); }
.cat-card[data-cat="gifts"]   { background: linear-gradient(160deg, #e6d4d0, #b88e87); }
.cat-name {
  position: relative;
  font-family: var(--font-serif);
  font-size: 22px; font-weight: 600; color: #1a1a1a;
}
.cat-count {
  position: relative;
  font-size: 13px; color: #2c2c2c; margin-top: 2px;
}

/* ============ Featured grid ============ */
.featured { padding: clamp(40px, 5vw, 72px) 0; }
.filters { display: flex; flex-wrap: wrap; gap: 8px; }
.chip {
  background: var(--surface);
  border: 1.5px solid var(--line);
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 14px; font-weight: 500;
  color: var(--ink);
  transition: background .15s ease, color .15s ease, border-color .15s ease;
  min-height: 36px;
}
.chip:hover { border-color: var(--ink); }
.chip.is-active {
  background: var(--ink); color: #fff; border-color: var(--ink);
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
}
.product {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
}
.product:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); border-color: var(--line-strong); }
.product-media {
  aspect-ratio: 4 / 5;
  position: relative;
  background: var(--surface-2);
  overflow: hidden;
}
.product-media::after {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(140% 90% at 30% 20%, rgba(255,255,255,.55), transparent 60%);
}
.product-badges {
  position: absolute; top: 10px; left: 10px;
  display: flex; flex-direction: column; gap: 6px;
  z-index: 1;
}
.badge {
  display: inline-block;
  font-size: 11px; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase;
  padding: 5px 9px; border-radius: 999px;
  background: var(--ink); color: #fff;
}
.badge-new   { background: #1f3d2b; }
.badge-sale  { background: var(--sale); }
.badge-low   { background: #5a4a1f; }

.product-body {
  padding: 14px 14px 16px;
  display: flex; flex-direction: column; gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--muted);
}
.product-name {
  font-family: var(--font-serif);
  font-size: 18px; font-weight: 600;
  margin: 0;
  color: var(--ink);
}
.product-foot {
  display: flex; justify-content: space-between; align-items: center;
  margin-top: auto; padding-top: 10px;
}
.price { font-size: 15px; font-weight: 600; color: var(--ink); }
.price-now { font-weight: 700; }
.price-was { color: var(--muted); text-decoration: line-through; margin-left: 6px; font-weight: 500; }
.add-btn {
  background: var(--surface-2);
  border: 1.5px solid var(--line-strong);
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 13px; font-weight: 600;
  color: var(--ink);
  min-height: 36px;
}
.add-btn:hover { background: var(--ink); color: #fff; border-color: var(--ink); }

/* Decorative product art (CSS gradients used as placeholder imagery) */
.art-1 { background: linear-gradient(160deg, #d8c3a5, #8c6a4a); }
.art-2 { background: linear-gradient(160deg, #cdd6cf, #6e8278); }
.art-3 { background: linear-gradient(160deg, #efe1d1, #b8916a); }
.art-4 { background: linear-gradient(160deg, #2d3a36, #5b7068); }
.art-5 { background: linear-gradient(160deg, #efe9df, #b8aa92); }
.art-6 { background: linear-gradient(160deg, #e6d4d0, #a87b73); }
.art-7 { background: linear-gradient(160deg, #d9dfe5, #7c8a96); }
.art-8 { background: linear-gradient(160deg, #ead9c2, #b08a5c); }

/* ============ Deals ============ */
.deals { padding: clamp(40px, 5vw, 72px) 0; background: var(--surface-2); }
.countdown { color: var(--muted); font-size: 14px; }
.countdown time { font-variant-numeric: tabular-nums; font-weight: 700; color: var(--ink); }
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: var(--gap);
}
.deal {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
}
.deal-feature { grid-row: span 1; }
.deal-feature .deal-art { aspect-ratio: 16 / 11; }
.deal-art { aspect-ratio: 4 / 3; background: var(--surface-2); }
.art-bundle { background: linear-gradient(150deg, #e0d4c0, #9c8160); }
.art-mug    { background: linear-gradient(150deg, #cfd8d3, #6a7c75); }
.art-tote   { background: linear-gradient(150deg, #efe1d1, #ad8a5e); }
.deal-body { padding: 18px 18px 20px; display: flex; flex-direction: column; gap: 8px; }
.deal-body h3 { font-size: clamp(20px, 2vw, 26px); }
.deal-body .badge { align-self: flex-start; }
.deal-body .btn { align-self: flex-start; margin-top: 6px; }

/* ============ Editorial ============ */
.editorial { padding: clamp(48px, 6vw, 88px) 0; }
.ed-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: var(--gap);
}
.ed-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  transition: transform .2s ease, box-shadow .2s ease;
}
.ed-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.ed-link { display: block; color: var(--ink); }
.ed-link:hover { text-decoration: none; }
.ed-link:hover h3 { color: var(--accent); }
.ed-art { aspect-ratio: 16 / 10; }
.ed-lead .ed-art { aspect-ratio: 4 / 3; }
.art-ed-1 { background: linear-gradient(160deg, #b8a280, #6e5a3e); }
.art-ed-2 { background: linear-gradient(160deg, #c9b89a, #8a7a5c); }
.art-ed-3 { background: linear-gradient(160deg, #97a8a0, #4f6259); }
.ed-body { padding: 18px 18px 22px; display: flex; flex-direction: column; gap: 10px; }
.ed-meta {
  display: flex; align-items: center; gap: 12px;
  font-size: 12px; color: var(--muted);
  text-transform: uppercase; letter-spacing: .1em;
}
.ed-tag {
  background: var(--surface-2);
  color: var(--ink);
  padding: 4px 10px; border-radius: 999px;
  font-weight: 600;
}
.ed-card h3 { font-size: clamp(18px, 1.8vw, 22px); transition: color .15s ease; }
.ed-lead h3 { font-size: clamp(22px, 2.4vw, 30px); }
.ed-body p:last-child { color: var(--ink-2); font-size: 15px; }

/* ============ Newsletter ============ */
.newsletter { padding: clamp(40px, 5vw, 72px) 0; background: var(--ink); color: #fff; }
.newsletter h2 { color: #fff; font-size: clamp(26px, 3vw, 36px); }
.newsletter p { color: #d8d2c7; max-width: 50ch; margin-top: 8px; }
.news-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: center;
}
.news-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: stretch;
}
.news-form input {
  border: 1.5px solid #4a4a4a;
  background: #2a2a2a;
  color: #fff;
  padding: 12px 16px;
  border-radius: 999px;
  font-size: 15px;
  min-height: 44px;
}
.news-form input::placeholder { color: #b8b3a8; }
.news-form input:focus { outline: 3px solid #9bbcff; outline-offset: 2px; border-color: #fff; }
.news-form input[aria-invalid="true"] { border-color: #ff9f8a; }
.news-form .btn-primary { background: #fff; color: var(--ink); border-color: #fff; }
.news-form .btn-primary:hover { background: var(--accent); color: #fff; border-color: var(--accent); }
.form-msg { grid-column: 1 / -1; min-height: 1.4em; font-size: 14px; color: #d8d2c7; }
.form-msg.is-error { color: #ffb4a3; }
.form-msg.is-success { color: #b8e6c1; }

/* ============ Footer ============ */
.site-footer { background: var(--surface-2); padding: 56px 0 24px; margin-top: 0; }
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: var(--gap);
  padding-bottom: 32px;
  border-bottom: 1px solid var(--line);
}
.foot-brand .brand-name { font-size: 24px; margin-bottom: 6px; }
.foot-brand p { color: var(--muted); max-width: 30ch; }
.site-footer h2 {
  font-family: var(--font-sans);
  font-size: 13px; font-weight: 700;
  text-transform: uppercase; letter-spacing: .12em;
  margin-bottom: 14px;
  color: var(--ink);
}
.site-footer nav ul { display: flex; flex-direction: column; gap: 10px; }
.site-footer nav a { color: var(--ink-2); font-size: 14px; }
.site-footer nav a:hover { color: var(--accent); }
.foot-base {
  display: flex; justify-content: space-between; flex-wrap: wrap;
  padding-top: 22px; gap: 12px;
  font-size: 13px; color: var(--muted);
}
.foot-base a { color: var(--muted); }
.foot-base a:hover { color: var(--accent); }

/* ============ Toast ============ */
.toast {
  position: fixed; left: 50%; bottom: 24px;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink); color: #fff;
  padding: 12px 18px; border-radius: 999px;
  font-size: 14px; font-weight: 500;
  box-shadow: var(--shadow-md);
  opacity: 0; pointer-events: none;
  transition: opacity .2s ease, transform .2s ease;
  z-index: 100;
  max-width: calc(100vw - 32px);
}
.toast.is-visible { opacity: 1; transform: translateX(-50%) translateY(0); }

/* ============ Responsive ============ */
@media (max-width: 1024px) {
  .header-inner { grid-template-columns: auto 1fr auto; }
  .primary-nav ul { gap: 18px; }
  .search { min-width: 180px; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-feature { grid-column: 1 / -1; }
  .ed-grid { grid-template-columns: 1fr 1fr; }
  .ed-lead { grid-column: 1 / -1; }
}
@media (max-width: 768px) {
  .header-inner {
    grid-template-columns: auto auto;
    grid-template-areas: "brand actions" "nav nav";
    row-gap: 10px;
  }
  .brand { grid-area: brand; }
  .header-actions { grid-area: actions; }
  .primary-nav { grid-area: nav; overflow-x: auto; }
  .primary-nav ul { justify-content: flex-start; gap: 16px; }
  .search { display: none; }
  .hero-grid { grid-template-columns: 1fr; }
  .hero-visual { min-height: 280px; aspect-ratio: 4 / 3; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .news-inner { grid-template-columns: 1fr; }
  .news-form { grid-template-columns: 1fr; }
  .news-form .btn-primary { justify-self: start; }
}
@media (max-width: 480px) {
  .cat-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-column: auto; }
  .ed-grid { grid-template-columns: 1fr; }
  .ed-lead { grid-column: auto; }
  .footer-grid { grid-template-columns: 1fr; }
  .hero-meta { gap: 10px 18px; }
}

/* ============ Reduced motion ============ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .001ms !important;
    transition-duration: .001ms !important;
    scroll-behavior: auto !important;
  }
}

/* ============ Forced colors ============ */
@media (forced-colors: active) {
  .btn, .chip, .add-btn, .icon-btn, .search, .product, .deal, .ed-card, .cat-card {
    border: 1px solid ButtonBorder;
  }
  .btn-primary, .news-form .btn-primary, .chip.is-active {
    background: ButtonText; color: ButtonFace; border-color: ButtonText;
  }
  .badge { background: ButtonText; color: ButtonFace; border: 1px solid ButtonBorder; }
  :focus-visible { outline: 3px solid Highlight; }
  a { color: LinkText; }
}
