  const grid = $('#product-grid');

  function renderProducts(filter = 'all') {
    const items = filter === 'all' ? PRODUCTS : PRODUCTS.filter(p => p.cat === filter);
    grid.innerHTML = items.map(p => {
      const badge = p.badge
        ? `<div class="product-badges"><span class="badge badge-${p.badge}">${BADGE_LABEL[p.badge]}</span></div>`
        : '';
      const priceHtml = p.was
        ? `<span class="price-now">${formatPrice(p.price)}</span> <span class="price-was"><span class="visually-hidden">Was </span>${formatPrice(p.was)}</span>`
        : `<span class="price-now">${formatPrice(p.price)}</span>`;
      return `
        <li class="product">
          <div class="product-media ${p.art}" role="img" aria-label="${p.name}">
            ${badge}
          </div>
          <div class="product-body">
            <p class="product-cat">${p.cat}</p>
            <h3 class="product-name">${p.name}</h3>
            <div class="product-foot">
              <p class="price">${priceHtml}</p>
              <button type="button" class="add-btn" data-add="${p.id}" aria-label="Add ${p.name} to cart">Add</button>
            </div>
          </div>
        </li>`;
    }).join('');
  }
  renderProducts();

  /* ---------- Filter chips ---------- */
  $$('.chip').forEach(chip => {
    chip.addEventListener('click', () => {
      $$('.chip').forEach(c => {
        c.classList.remove('is-active');
        c.setAttribute('aria-pressed', 'false');
      });
      chip.classList.add('is-active');
      chip.setAttribute('aria-pressed', 'true');
      renderProducts(chip.dataset.filter);
    });
  });

  /* ---------- Cart ---------- */
  let cart = 0;
  const cartCountEl = document.querySelector('[data-cart-count]');
  const cartBtn = $('#cart-btn');

  function updateCart(n) {
    cart += n;
    cartCountEl.textContent = String(cart);
    cartBtn.setAttribute('aria-label', `Cart, ${cart} ${cart === 1 ? 'item' : 'items'}`);
  }

  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-add]');
    if (!btn) return;
    const product = PRODUCTS.find(p => p.id === btn.dataset.add);
    if (!product) return;
    updateCart(1);
    showToast(`Added "${product.name}" to cart`);
  });

  cartBtn.addEventListener('click', () => {
    showToast(cart === 0 ? 'Your cart is empty' : `${cart} ${cart === 1 ? 'item' : 'items'} in cart`);
  });

  /* ---------- Toast ---------- */
  const toast = $('#toast');
  let toastTimer;
  function showToast(msg) {
    toast.textContent = msg;
