  const newsForm = $('#news-form');
  const newsInput = $('#news-email');
  const newsMsg = $('#news-msg');
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  newsForm.addEventListener('submit', (e) => {
