    if (!emailRe.test(value)) {
      newsInput.setAttribute('aria-invalid', 'true');
      newsInput.setAttribute('aria-describedby', 'news-msg');
      newsMsg.textContent = 'Please enter a valid email address.';
      newsMsg.classList.add('is-error');
      newsInput.focus();
      return;
    }
    newsInput.removeAttribute('aria-invalid');
    newsMsg.textContent = 'Thanks — check your inbox to confirm your subscription.';
    newsMsg.classList.add('is-success');
    newsForm.reset();
  });

  /* ---------- Countdown ---------- */
  const cdEl = $('#countdown');
  function updateCountdown() {
    const now = new Date();
    const end = new Date(now);
    const day = end.getDay();
    const daysUntilSunday = (7 - day) % 7 || 7;
    end.setDate(end.getDate() + daysUntilSunday);
    end.setHours(23, 59, 59, 0);
    let diff = Math.max(0, end - now);
    const d = Math.floor(diff / 86400000); diff -= d * 86400000;
    const h = Math.floor(diff / 3600000);  diff -= h * 3600000;
    const m = Math.floor(diff / 60000);    diff -= m * 60000;
    const s = Math.floor(diff / 1000);
    const pad = (n) => String(n).padStart(2, '0');
    cdEl.textContent = `${d}d ${pad(h)}h ${pad(m)}m ${pad(s)}s`;
    cdEl.setAttribute('datetime', `P${d}DT${h}H${m}M${s}S`);
  }
  updateCountdown();
  setInterval(updateCountdown, 1000);

  /* ---------- Smooth in-page nav (respect reduced motion) ---------- */
  const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (!prefersReduced) {
    document.querySelectorAll('a[href^="#"]').forEach(a => {
      a.addEventListener('click', (e) => {
        const id = a.getAttribute('href');
        if (id.length < 2) return;
        const target = document.querySelector(id);
        if (!target) return;
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        target.setAttribute('tabindex', '-1');
        target.focus({ preventScroll: true });
      });
    });
  }
})();
